out=[]
for c in content:
  b=base[c['id']];m={**b,**c};m['size']=b['size'];
  if c['id']=='communicator': m['checkAxes']=[1,1,1]; m['sizeBasis']='printed W.O.A × L.O.A × H.O.A, checked on the closed pose'
  m['specs']=[{k:v for k,v in s.items() if v is not None} for s in c['specs']]
